This stage looks at every section header in a :class:`DoclingDocument` and
assigns it a ``level`` that reflects the document's logical nesting. Levels can
be derived from the numbering scheme of a heading (``1.``, ``1.1``, ``(a)``,
``(i)``, ``PART I`` ...) and/or from visual style cues (bounding-box height).

The resulting levels are what Markdown (and other structured) exports use to
decide the heading depth, e.g. a level-1 heading renders as ``# heading`` and a
level-2 heading as ``## heading``.
"""

import logging
import re
from dataclasses import dataclass
from typing import Optional

from docling_core.types.doc import DoclingDocument, SectionHeaderItem

from docling.datamodel.pipeline_options import HeadingHierarchyOptions

_log = logging.getLogger(__name__)

# Uppercase Roman-numeral letters, used both for "roman_u" markers ("IV.") and
# for parenthetical Roman markers ("(ii)").
_ROMAN_LETTERS = "IVXLCDM"

# Matchers for the recognized numbering families, evaluated in order. The order
# matters: more specific / longer patterns must be tried before the shorter
# ones they could otherwise shadow (e.g. "decimal2" before "decimal", and
# "paren_roman" before "paren_alpha").
_PART_RE = re.compile(r"^\s*PART\b", re.IGNORECASE)
_ARTICLE_RE = re.compile(r"^\s*(ARTICLE\b|ART\.)", re.IGNORECASE)
_DECIMAL2_RE = re.compile(r"^\s*\d+(?:\.\d+)+")
_DECIMAL_RE = re.compile(r"^\s*\d+\.?(?:\s|$)")
_PAREN_RE = re.compile(r"^\s*\(([A-Za-z]+)\)")
_ROMAN_U_RE = re.compile(r"^\s*([IVXLCDM]+)[.)]")
_ALPHA_U_RE = re.compile(r"^\s*([A-Z])[.)]")


def _is_roman(token: str) -> bool:
    """Return True if ``token`` is composed solely of Roman-numeral letters."""
    upper = token.upper()
    return len(upper) > 0 and all(ch in _ROMAN_LETTERS for ch in upper)


@dataclass(frozen=True)
class NumberingMarker:
    """A recognized numbering marker at the start of a heading.

    Attributes:
        family: Identifier of the numbering scheme this marker belongs to, e.g.
            ``"part"``, ``"decimal"``, ``"decimal2"``, ``"paren_alpha"``,
            ``"paren_roman"``, ``"roman_u"``, ``"alpha_u"`` or ``"article"``.
        text: The raw marker text that was matched.
    """

    family: str
    text: str


def _parse_marker(text: str) -> Optional[NumberingMarker]:
    """Parse the leading numbering marker of a heading.

    Args:
        text: The heading text, optionally prefixed by a numbering marker.

    Returns:
        A :class:`NumberingMarker` describing the recognized family, or
        ``None`` when the heading carries no recognized numbering marker
        (i.e. plain-text headings).
    """
    if not text:
        return None

    # Keyword-based legal families first: "PART I", "Article 5". These would
    # otherwise be misread as Roman/alpha markers by their trailing token.
    if _PART_RE.match(text):
        return NumberingMarker(family="part", text=_PART_RE.match(text).group(0).strip())
    if _ARTICLE_RE.match(text):
        return NumberingMarker(
            family="article", text=_ARTICLE_RE.match(text).group(0).strip()
        )

    # Decimal families: double/multi-decimal ("1.1") before single ("1.").
    m = _DECIMAL2_RE.match(text)
    if m:
        return NumberingMarker(family="decimal2", text=m.group(0).strip())
    m = _DECIMAL_RE.match(text)
    if m:
        return NumberingMarker(family="decimal", text=m.group(0).strip())

    # Parenthetical families: multi-character Roman ("(ii)") is unambiguous, a
    # single letter ("(a)", "(i)") is treated as an alphabetic marker.
    m = _PAREN_RE.match(text)
    if m:
        token = m.group(1)
        if len(token) >= 2 and _is_roman(token):
            return NumberingMarker(family="paren_roman", text=m.group(0).strip())
        if len(token) == 1 and token.isalpha():
            return NumberingMarker(family="paren_alpha", text=m.group(0).strip())
        return None

    # Dotted uppercase families: Roman ("IV.") before single-letter alpha ("A.").
    m = _ROMAN_U_RE.match(text)
    if m and _is_roman(m.group(1)):
        return NumberingMarker(family="roman_u", text=m.group(0).strip())
    m = _ALPHA_U_RE.match(text)
    if m:
        return NumberingMarker(family="alpha_u", text=m.group(0).strip())

    return None


def _infer_from_numbering(
    headings: list, options: HeadingHierarchyOptions
) -> dict[int, int]:
    """Infer heading levels from their numbering markers.

    Each heading is classified into a numbering scheme (family). Only the
    schemes that actually appear in the document are ranked, using the
    precedence defined by ``options.numbering_schemes`` (outermost first).
    Schemes present in the document but absent from that list are appended in
    order of first appearance. Levels are therefore relative to the document:
    a document that only uses single- and double-decimal numbering yields
    levels ``1`` and ``2`` regardless of the schemes' global precedence.

    Args:
        headings: Objects exposing a ``.text`` attribute.
        options: Configuration controlling scheme precedence.

    Returns:
        A mapping from heading index to inferred level. Headings without a
        recognized numbering marker are omitted.
    """
    families: dict[int, str] = {}
    for idx, heading in enumerate(headings):
        marker = _parse_marker(getattr(heading, "text", "") or "")
        if marker is not None:
            families[idx] = marker.family

    if not families:
        return {}

    present = set(families.values())

    # Rank present schemes: first those named in the configured precedence
    # order, then any remaining ones by their order of first appearance.
    ranked: list[str] = [
        scheme for scheme in options.numbering_schemes if scheme in present
    ]
    for idx in sorted(families):
        scheme = families[idx]
        if scheme not in ranked:
            ranked.append(scheme)

    scheme_level = {scheme: level for level, scheme in enumerate(ranked, start=1)}
    return {idx: scheme_level[family] for idx, family in families.items()}


class HeadingHierarchyModel:
    """Assign hierarchical levels to the section headers of a document."""

    def __init__(self, options: HeadingHierarchyOptions) -> None:
        self.options = options

    def _clamp(self, level: int) -> int:
        """Clamp ``level`` to the valid range and the configured maximum."""
        level = max(1, level)
        if self.options.max_level and self.options.max_level > 0:
            level = min(level, self.options.max_level)
        return level

    def _levels_from_style(
        self, headings: list[SectionHeaderItem]
    ) -> dict[int, int]:
        """Rank headings by bounding-box height (taller headings are shallower)."""
        heights: dict[int, float] = {}
        for idx, heading in enumerate(headings):
            if heading.prov:
                heights[idx] = heading.prov[0].bbox.height

        if not heights:
            return {}

        # Distinct heights, tallest first -> level 1, 2, 3, ...
        unique = sorted(set(heights.values()), reverse=True)
        rank = {height: level for level, height in enumerate(unique, start=1)}
        return {idx: rank[height] for idx, height in heights.items()}

